import { guidanceWarning } from '../types/guidance';
import { snapshotGuidance, validateGuidanceBudget } from './guidanceDelivery';
import { ProjectStorage } from './ProjectStorage';
import {
  profileContextInputs,
  profileReferenceMode,
  recordProfileRequest,
} from './profiles/profileContext';
import { assertProfileAccount } from './profiles/profileAccount';
import { assertGenerationGuidance } from './generationGuidance';
import { randomUUID } from 'crypto';
import {
  createVariantContextBundle,
  retainedReferenceMetadata,
} from '../agent-variants/variantContext';
import type { ActiveVariantSnapshot } from '../agent-variants/contracts';
import { createLogger } from '../index-core';
import { AgentVariantsError } from '../agent-variants';
import type {
  AgentVariantsOrchestrator,
  ActiveSnapshot,
  RequestWorkResult,
  ReportCompleteResult,
  WorkItemStatus,
} from '../agent-variants';
import {
  collectStaticPreviewRefineTargetInstructions,
  withDerivedStaticPreviewTargets,
} from '../mcp/changeBatchClassification';
import type {
  ChangeRequest,
  CommentChangeItem,
} from '../types/change-request-types';
import { assertNativeWorkerSelection } from '../agent-variants/workerRuntime';
import {
  VariantGenerationService,
  type VariantRequestResult,
} from './VariantGenerationService';
import { SessionBridgeService } from './SessionBridgeService';
import {
  EXECUTOR_LEASE_OWNER,
  chooseWorkerLeaseOwner,
  type WorkerExecutorService,
} from '../agent-variants/WorkerExecutorService';
import type { VariantHistoryService } from './VariantHistoryService';

const log = createLogger('VariantRunService');
const MAX_RELEVANT_FILES = 12;

const relevantFilesForTarget = (request: ChangeRequest): string[] =>
  Array.from(
    new Set(
      [
        ...request.sourceFiles,
        ...request.changes.flatMap((change) =>
          'element' in change ? (change.element.filePaths ?? []) : [],
        ),
      ]
        .map((file) => file.trim())
        .filter(Boolean),
    ),
  ).slice(0, MAX_RELEVANT_FILES);

export type VariantRunServiceOptions = {
  history?: VariantHistoryService;
  prepareGuidance?: (request: ChangeRequest) => Promise<ChangeRequest>;
  prepareProfile?: (request: ChangeRequest) => Promise<ChangeRequest>;
  bridge: SessionBridgeService;
  storage?: ProjectStorage;
  onGeneratedProject?: (projectPath: string) => Promise<void>;
  orchestrator: AgentVariantsOrchestrator;
  projectPath?: string;
  staticEntry?: string;
  createSessionId?: () => string;
  executor?: WorkerExecutorService;
};

export type HostWorkCompletionResult = ReportCompleteResult & {
  acceptedStatus: WorkItemStatus;
  alreadyCompleted?: true;
  variant: ActiveVariantSnapshot | null;
};

export class VariantRunService {
  private activeIntakes = 0;
  private readonly storage?: ProjectStorage;
  private readonly projectPath?: string;
  private readonly prepareProfile?: VariantRunServiceOptions['prepareProfile'];
  private readonly prepareGuidance?: VariantRunServiceOptions['prepareGuidance'];
  private readonly bridge: SessionBridgeService;
  private readonly orchestrator: AgentVariantsOrchestrator;
  private readonly executor?: WorkerExecutorService;
  private readonly history?: VariantHistoryService;
  private readonly elementVariantService: VariantGenerationService;

  constructor(options: VariantRunServiceOptions) {
    this.prepareProfile = options.prepareProfile;
    this.history = options.history;
    this.prepareGuidance = options.prepareGuidance;
    this.storage = options.storage;
    this.projectPath = options.projectPath;
    this.bridge = options.bridge;
    this.orchestrator = options.orchestrator;
    this.executor = options.executor;
    this.elementVariantService = new VariantGenerationService({
      bridge: options.bridge,
      storage: options.storage,
      onGeneratedProject: options.onGeneratedProject,
      orchestrator: options.orchestrator,
      projectPath: options.projectPath,
      staticEntry: options.staticEntry,
      createSessionId: options.createSessionId,
      ...(options.executor ? { executor: options.executor } : {}),
      recordGuidance: (args) => this.recordGuidance(args),
    });
  }

  async startElementVariants(
    request: ChangeRequest,
  ): Promise<VariantRequestResult> {
    return this.runRequest(request, (prepared) =>
      this.elementVariantService.processVariantRequest(prepared),
    );
  }

  refineVariant(args: {
    sessionId: string;
    variantId: string;
    instruction: string;
    leaseOwner: string;
  }): RequestWorkResult {
    return this.orchestrator.refineVariant(args);
  }

  async completeHostWork(args: {
    sessionId: string;
    workItemId: string;
    status: 'succeeded' | 'failed' | 'cancelled';
    output?: unknown;
    error?: { code: string; message: string };
    title?: string;
    description?: string;
  }): Promise<HostWorkCompletionResult> {
    const readVariant = (): ActiveVariantSnapshot | null => {
      const input = this.orchestrator.getVariantWorkItemInput(
        args.sessionId,
        args.workItemId,
      );
      const variantId =
        input && 'variantId' in input ? input.variantId : args.workItemId;
      return (
        this.orchestrator
          .getVariants(args.sessionId)
          .find((variant) => variant.workItemId === variantId) ?? null
      );
    };
    const workItem = this.orchestrator
      .getHostWork(args.sessionId)
      .find((item) => item.workId === args.workItemId);
    if (!workItem) {
      const acceptedStatus = this.orchestrator.getWorkItemStatus(
        args.sessionId,
        args.workItemId,
      );
      if (
        acceptedStatus === 'succeeded' ||
        acceptedStatus === 'failed' ||
        acceptedStatus === 'cancelled'
      ) {
        return {
          stage: this.orchestrator.getStage(args.sessionId),
          progress: this.orchestrator.getProgress(args.sessionId),
          acceptedStatus,
          alreadyCompleted: true,
          variant: readVariant(),
        };
      }
      throw new AgentVariantsError(
        'INVALID_STAGE_ACTION',
        `Host work item ${args.workItemId} is ${acceptedStatus} and has no active lease`,
      );
    }
    if (
      (workItem.kind === 'static_preview' ||
        workItem.kind === 'refine_variant') &&
      args.output !== undefined
    ) {
      throw new AgentVariantsError(
        'SCHEMA_VALIDATION_FAILED',
        'Static host work completes from its assigned workspace; do not send inline output.',
      );
    }
    const output =
      args.output ??
      (workItem.kind === 'code_gen' &&
      workItem.workspace.kind === 'git_worktree'
        ? { worktreePath: workItem.workspace.rootPath, changedFiles: [] }
        : undefined);
    const result = await this.orchestrator.reportComplete({
      sessionId: args.sessionId,
      workItemId: args.workItemId,
      leaseId: workItem.leaseId,
      attempt: workItem.attempt,
      status: args.status,
      ...(output !== undefined ? { output } : {}),
      ...(args.error ? { error: args.error } : {}),
      ...(args.title ? { title: args.title } : {}),
      ...(args.description ? { description: args.description } : {}),
    });
    this.bridge.reportFeedback('__RIVET_REFRESH_GIT__');
    if (result.requeuedForRegeneration) {
      this.orchestrator.requestWork({
        sessionId: args.sessionId,
        workItemIds: [args.workItemId],
        leaseOwner: 'rivet-host-agent',
      });
      return { ...result, acceptedStatus: 'pending', variant: readVariant() };
    }
    const acceptedStatus = this.orchestrator.getWorkItemStatus(
      args.sessionId,
      args.workItemId,
    );
    return { ...result, acceptedStatus, variant: readVariant() };
  }

  async refineStaticPreviewBatch(
    request: ChangeRequest,
  ): Promise<VariantRequestResult> {
    return this.runRequest(request, (prepared) =>
      this.startStaticPreviewRefinements(prepared),
    );
  }

  private async runRequest(
    request: ChangeRequest,
    generate: (prepared: ChangeRequest) => Promise<VariantRequestResult>,
  ): Promise<VariantRequestResult> {
    assertNativeWorkerSelection({
      initiator: request.initiator,
      selection: request.workerSelection,
    });
    const prepared = await this.prepareRequest(request);
    this.activeIntakes += 1;
    this.bridge.setStatus('APPLYING');
    try {
      const result = await generate(prepared);
      return await this.withProfileContext(prepared, result);
    } finally {
      this.activeIntakes -= 1;
      if (this.activeIntakes === 0) this.bridge.setStatus('READY');
    }
  }

  private async withProfileContext(
    request: ChangeRequest,
    result: VariantRequestResult,
  ): Promise<VariantRequestResult> {
    if (!result.success) return result;
    const profileContext = await recordProfileRequest(request);
    assertGenerationGuidance(request);
    const warning = guidanceWarning(request.guidance ?? []);
    return {
      ...result,
      ...(warning ? { guidanceWarning: warning } : {}),
      guidance: (request.guidance ?? []).map(({ id, title }) => ({
        id,
        title,
      })),
      ...(profileContext ? { profileContext } : {}),
    };
  }

  private async prepareRequest(request: ChangeRequest): Promise<ChangeRequest> {
    const prepared = this.prepareGuidance
      ? await this.prepareGuidance(request)
      : request;
    assertGenerationGuidance(prepared);
    const projectPath = this.projectPath ?? this.bridge.getProjectPath();
    if (
      prepared.guidance?.some(
        (document) =>
          document.attachments?.length ||
          document.references?.some(
            (reference) =>
              reference.kind !== 'directory' && reference.files?.length,
          ),
      ) &&
      !projectPath
    )
      throw new Error(
        'Guidance files require a project path for their retained context.',
      );
    validateGuidanceBudget(prepared);
    const guidance = projectPath
      ? await snapshotGuidance({
          documents: prepared.guidance ?? [],
          dataDirectory: (this.storage ?? new ProjectStorage()).resolve(
            projectPath,
          ).dataDirectory,
        })
      : prepared.guidance;
    const illustrated = { ...prepared, guidance };
    const resolved = this.prepareProfile
      ? await this.prepareProfile(illustrated)
      : illustrated;
    assertGenerationGuidance(resolved);
    validateGuidanceBudget(resolved);
    return {
      ...resolved,
      guidance: resolved.guidance ?? [],
      agentRunId: resolved.agentRunId ?? resolved.traceId ?? randomUUID(),
    };
  }

  private recordGuidance(args: {
    request: ChangeRequest;
    workItemIds: string[];
  }): void {
    if (!this.history) return;
    const projectPath = this.projectPath ?? this.bridge.getProjectPath();
    const requestId = args.request.agentRunId ?? args.request.traceId;
    if (!projectPath || !requestId)
      throw new Error(
        'Cannot retain saved context without a project and request ID.',
      );
    assertGenerationGuidance(args.request);
    this.history.recordGuidance({
      projectPath,
      requestId,
      workItemIds: args.workItemIds,
      guidance: args.request.guidance ?? [],
      accountId: args.request.guidanceAccountId,
    });
    assertGenerationGuidance(args.request);
  }

  private async startStaticPreviewRefinements(
    prepared: ChangeRequest,
  ): Promise<VariantRequestResult> {
    const assertContext = () => {
      assertGenerationGuidance(prepared);
      for (const change of prepared.changes)
        if (change.kind === 'comment') assertProfileAccount(change);
    };
    assertContext();
    const request = prepared;
    const derived = withDerivedStaticPreviewTargets(prepared);
    const targets = collectStaticPreviewRefineTargetInstructions(derived);
    const sessionId = targets[0]?.target.sessionId;
    if (!sessionId) {
      return {
        success: false,
        error: 'Static preview refine batch carries no target',
      };
    }

    const contextForTarget = (
      target: NonNullable<ChangeRequest['staticPreviewTarget']>,
    ) => {
      const comments = derived.changes.filter(
        (change): change is CommentChangeItem => {
          if (change.kind !== 'comment' || !change.variantRequest) return false;
          const sourceTarget =
            change.staticPreviewTarget ?? derived.staticPreviewTarget;
          return (
            sourceTarget?.sessionId === target.sessionId &&
            sourceTarget?.variantId === target.variantId
          );
        },
      );
      const mode = comments.some(
        (change) => profileReferenceMode(change) === 'replace',
      )
        ? 'replace'
        : 'inherit';
      const inputs = comments.map(profileContextInputs);
      const userContextInputs = inputs.flatMap(
        (input) => input.userContextInputs,
      );
      const savedContextInputs = inputs.flatMap(
        (input) => input.profileContextInputs,
      );
      const source = this.orchestrator.getVariantWorkItemInput(
        target.sessionId,
        target.variantId,
      );
      const inherited = retainedReferenceMetadata({
        source: source?.context,
        sourceReferenceMetadata: source?.references,
        profileReferenceMode: mode,
      });
      for (const comment of comments) {
        if (comment.profileTrace && inherited?.length)
          comment.profileTrace.inheritedReferences = inherited;
      }
      const additionalContext =
        (userContextInputs.length ||
          savedContextInputs.length ||
          mode === 'replace') &&
        this.projectPath &&
        this.storage
          ? createVariantContextBundle({
              sessionId: randomUUID(),
              prompt: '',
              workspaceRoot: this.projectPath,
              dataDirectory: this.storage.resolve(this.projectPath)
                .dataDirectory,
              userContextInputs,
              profileContextInputs: savedContextInputs,
            })
          : undefined;
      return { additionalContext, mode } as const;
    };

    const workerLease = await chooseWorkerLeaseOwner(this.executor, {
      initiator: request.initiator,
      selection: request.workerSelection,
    });

    this.bridge.reportFeedback(
      targets.some((target) => target.count != null)
        ? 'Generating new directions from this design.'
        : 'Refining this design in place.',
    );

    let droppedRefinements: Array<{ variantId: string; reason: string }> = [];
    let createdWorkItemIds: string[] = [];
    try {
      assertContext();
      ({ droppedRefinements, createdWorkItemIds } =
        this.orchestrator.beginStaticPreviewRefinements({
          beforeDispatch: (workItemIds) =>
            this.recordGuidance({ request: prepared, workItemIds }),
          sessionId,
          targets: targets.map(
            ({
              target,
              instruction,
              count,
              briefs,
              runLabel,
              fidelity,
              element,
              requestId,
            }) => {
              const relevantFiles = relevantFilesForTarget(derived);
              const context =
                count != null ? contextForTarget(target) : undefined;
              const additionalContext = context?.additionalContext;
              return {
                workerSelection: request.workerSelection,
                guidance: prepared.guidance ?? [],
                variantId: target.variantId,
                profileReferenceMode: context?.mode,
                instruction,
                count,
                ...(briefs ? { briefs } : {}),
                ...(runLabel ? { runLabel } : {}),
                ...(fidelity ? { fidelity } : {}),
                ...(relevantFiles.length > 0 ? { relevantFiles } : {}),
                element,
                requestId,
                ...(count != null && additionalContext
                  ? {
                      additionalContext: {
                        ...additionalContext,
                        userContext: additionalContext.userContext
                          .filter((source) => source.transport !== 'prompt')
                          .map((source) => ({
                            ...source,
                            id: `${additionalContext.sessionId}_${source.id}`,
                          })),
                      },
                    }
                  : {}),
              };
            },
          ),
        }));
    } catch (error) {
      if (!(error instanceof AgentVariantsError)) throw error;
      const message = error.message;
      log.warn(`Static preview refine intake failed: ${message}`);
      this.bridge.reportFeedback(`Refinement failed: ${message}`);
      return { success: false, error: message };
    }

    for (const dropped of droppedRefinements) {
      this.bridge.reportFeedback(
        `Refinement skipped for one design: ${dropped.reason}`,
      );
    }

    if (createdWorkItemIds.length > 0) {
      try {
        assertContext();
      } catch (error) {
        await Promise.all(
          createdWorkItemIds.map((variantId) =>
            this.orchestrator.cancelVariant({ sessionId, variantId }),
          ),
        );
        throw error;
      }
      log.info(`refine workers: ${workerLease.summary}`);
      this.orchestrator.setWorkerRuntime(sessionId, workerLease.summary);
      if (workerLease.runtime) {
        const lease = this.orchestrator.requestWork({
          sessionId,
          workItemIds: createdWorkItemIds,
          leaseOwner: EXECUTOR_LEASE_OWNER,
        });
        this.bridge.reportFeedback(
          `Rivet is building ${createdWorkItemIds.length} direction(s) with its own workers — watch status for progress.`,
        );
        void this.executor
          ?.run(
            sessionId,
            createdWorkItemIds,
            {
              leaseId: lease.leaseId,
              items: lease.leasedWorkItems,
            },
            workerLease.runtime,
            workerLease,
          )
          .catch((error: unknown) =>
            log.warn('worker executor run failed', error),
          );
      } else {
        if (this.executor) {
          this.bridge.reportFeedback(
            `Directions will run via ${workerLease.summary}.`,
          );
        }
        this.orchestrator.requestWork({
          sessionId,
          workItemIds: createdWorkItemIds,
          leaseOwner: 'rivet-host-agent',
        });
      }
    }

    if (droppedRefinements.length > 0) {
      return {
        success: createdWorkItemIds.length > 0,
        error: droppedRefinements[0]?.reason,
      };
    }
    return { success: true };
  }

  cancelVariants(args: {
    sessionId: string;
    reason?: string;
  }): ReturnType<AgentVariantsOrchestrator['cancel']> {
    this.executor?.cancelSession(args.sessionId);
    return this.orchestrator.cancel(args);
  }

  interruptWorkers(): void {
    const sessionId = this.orchestrator.getActiveSessionId();
    if (sessionId) this.executor?.cancelSession(sessionId);
  }

  getSnapshot(): ActiveSnapshot {
    return this.orchestrator.buildActiveSnapshot();
  }
}
